// Global Application State
let currentTimeframe = '90d';
let currentViewMode = 'executive';
let currentTheme = localStorage.getItem('octane_saas_theme') || 'light';
let JOURNEY_DATA = TIMEFRAMES_DATA['90d'] || {};
let STICKY_NOTES = JSON.parse(JSON.stringify(DEFAULT_STICKY_NOTES || []));
let STICKY_CONNECTIONS = JSON.parse(JSON.stringify(DEFAULT_STICKY_CONNECTIONS || []));
let gscVisibleMetrics = { clicks: true, impressions: true, ctr: true, position: true };
let activeSchemaId = 1;
let activeChannelKey = 'organic_search';
let activeOriginKey = 'gsc_search';
let activeOriginTitle = 'Google Search Console (GSC Index)';
let activeQueryText = '';
let activeLandingPath = '/home';
let activeFlowPath = '';
let activeCategoryFilter = 'all';
let isConnectingMode = false;
let connectingSourceId = null;

// Canvas Pan & Zoom State
let canvasScale = 1.0;
let canvasPanX = 0;
let canvasPanY = 0;
let isPanning = false;
let startPanX = 0;
let startPanY = 0;
let isSpacePressed = false;

// 1. Theme Management (Light / Dark)
function initTheme() {
  // Enforce pure white boxes and black text light mode baseline
  if (!localStorage.getItem('octane_saas_theme')) {
    currentTheme = 'light';
  }
  document.documentElement.setAttribute('data-theme', currentTheme);
  updateThemeToggleIcon();
}

function toggleTheme() {
  currentTheme = currentTheme === 'light' ? 'dark' : 'light';
  document.documentElement.setAttribute('data-theme', currentTheme);
  localStorage.setItem('octane_saas_theme', currentTheme);
  updateThemeToggleIcon();
  if (currentViewMode === 'explorer') {
    requestAnimationFrame(redrawAllEdges);
  }
}

function updateThemeToggleIcon() {
  const btn = document.getElementById('btn-theme-toggle');
  if (btn) {
    btn.innerHTML = currentTheme === 'light' ? '🌙' : '☀️';
    btn.title = `Switch to ${currentTheme === 'light' ? 'Dark' : 'Light'} Mode`;
  }
}

// 2. View Mode Switcher
function switchViewMode(mode, triggerBtn) {
  currentViewMode = mode;
  document.querySelectorAll('.segmented-nav-btn').forEach(b => b.classList.remove('active'));
  if (triggerBtn) triggerBtn.classList.add('active');

  const execView = document.getElementById('executive-view');
  const canvasViewport = document.getElementById('canvas-viewport');
  const zoomHud = document.getElementById('canvas-zoom-hud');

  if (mode === 'executive') {
    if (execView) execView.classList.remove('hidden');
    if (canvasViewport) canvasViewport.classList.add('hidden');
    if (zoomHud) zoomHud.style.display = 'none';
  } else {
    if (execView) execView.classList.add('hidden');
    if (canvasViewport) canvasViewport.classList.remove('hidden');
    if (zoomHud) zoomHud.style.display = 'flex';
    requestAnimationFrame(() => {
      renderStage1();
      redrawAllEdges();
      renderAllStickyNotes();
    });
  }
}

// 3. Timeframe Switching
function setTimeframe(tfKey, btnEl) {
  currentTimeframe = tfKey;
  JOURNEY_DATA = TIMEFRAMES_DATA[tfKey] || TIMEFRAMES_DATA['90d'];

  document.querySelectorAll('.timeframe-btn').forEach(b => b.classList.remove('active'));
  if (btnEl) btnEl.classList.add('active');

  updateExecutiveBriefing();
  renderGscChart(tfKey);

  if (currentViewMode === 'explorer') {
    renderStage1();
    redrawAllEdges();
  }
}

// 4. Executive Briefing Updates
function updateExecutiveBriefing() {
  const d = JOURNEY_DATA;
  if (!d) return;

  // KPI 1: Inbound Leads (Marketing Attributed Only)
  const tfKey = (d && d.timeframe) ? d.timeframe : '90d';
  const mktCounts = {
    '24h': { mkt: 0, direct: 0, demos: 0 },
    '7d': { mkt: 0, direct: 1, demos: 0 },
    '30d': { mkt: 16, direct: 68, demos: 4 },
    '90d': { mkt: 19, direct: 79, demos: 6 }
  };
  const stats = mktCounts[tfKey] || mktCounts['90d'];
  const leadsVal = document.getElementById('kpi-leads-val');
  if (leadsVal) leadsVal.textContent = `${stats.mkt} Marketing Leads`;
  const demosVal = document.getElementById('kpi-demos-val');
  if (demosVal) {
    if (stats.mkt > 0) {
      demosVal.textContent = `${stats.demos} Demos Booked · (${stats.direct} Direct CRM excluded)`;
    } else {
      demosVal.textContent = `0 Inbound (${stats.direct} Direct CRM excluded)`;
    }
  }

  // KPI 2: Free Google Traffic
  const orgChannel = (d.channels || []).find(c => c.id === 'organic_search') || (d.channels || [])[0];
  if (orgChannel) {
    const searchVal = document.getElementById('kpi-search-val');
    if (searchVal) searchVal.textContent = `${orgChannel.share || '43.0%'} of All Visitors`;
    const sessVal = document.getElementById('kpi-sessions-val');
    if (sessVal) sessVal.textContent = `${(orgChannel.sessions || 1185).toLocaleString()} Free Visits ($0 Spent on Ads)`;
  }

  // KPI 3: Blog Traffic
  const blog = d.blogPerformance || { clicks: 902, impressions: 309741, blogCount: 269 };
  const blogVal = document.getElementById('kpi-blog-val');
  if (blogVal) blogVal.textContent = `${blog.clicks.toLocaleString()} Total Visits`;
  const blogImp = document.getElementById('kpi-blog-imp-val');
  if (blogImp) {
    const impStr = blog.impressions >= 1000000 ? (blog.impressions/1000000).toFixed(1) + 'M' : (blog.impressions >= 1000 ? (blog.impressions/1000).toFixed(1) + 'K' : blog.impressions);
    blogImp.textContent = `${impStr} Impressions (${blog.blogCount || 269} Active Blogs)`;
  }

  // KPI 4: Google Rankings
  const top3 = (d.gscQueries || []).filter(q => q.isTopRank).length || 21;
  const top3Val = document.getElementById('kpi-top3-val');
  if (top3Val) top3Val.textContent = `${top3} Top 3 Keywords`;

  // Strip Telemetry Tags
  const tagGa4 = document.getElementById('status-tag-ga4');
  if (tagGa4) tagGa4.innerHTML = `✓ GA4 Live (${(d.totalSessions || 2704).toLocaleString()} Sessions)`;
  const tagGsc = document.getElementById('status-tag-gsc');
  if (tagGsc) tagGsc.innerHTML = `🔍 Search Console Live (${top3} Top 3 Ranks)`;
  const tagHs = document.getElementById('status-tag-hubspot');
  if (tagHs) tagHs.innerHTML = `🏆 HubSpot CRM Live (${stats.mkt} Marketing Leads)`;

  // GSC Performance Scorecards
  const ds = GSC_CHART_DATASETS[currentTimeframe] || GSC_CHART_DATASETS['90d'];
  if (ds) {
    const totalClicks = ds.clicks.reduce((a, b) => a + b, 0);
    const totalImp = ds.impressions.reduce((a, b) => a + b, 0);
    const exactCtr = totalImp > 0 ? ((totalClicks / totalImp) * 100).toFixed(2) + '%' : '0.00%';
    let weightedPos = 0;
    for (let i = 0; i < ds.position.length; i++) weightedPos += (ds.position[i] || 12.2) * (ds.impressions[i] || 1);
    const exactPos = totalImp > 0 ? (weightedPos / totalImp).toFixed(1) : '12.2';

    const numClicks = document.getElementById('gsc-val-clicks');
    if (numClicks) numClicks.textContent = totalClicks.toLocaleString();
    const numImp = document.getElementById('gsc-val-impressions');
    if (numImp) numImp.textContent = totalImp >= 1000 ? (totalImp / 1000).toFixed(1) + 'K' : totalImp.toLocaleString();
    const numCtr = document.getElementById('gsc-val-ctr');
    if (numCtr) numCtr.textContent = exactCtr;
    const numPos = document.getElementById('gsc-val-position');
    if (numPos) numPos.textContent = exactPos;
  }
}

// 5. GSC Multi-Metric SVG Spline Chart
function renderGscChart(tfKey) {
  const svg = document.getElementById('gsc-perf-chart-svg');
  if (!svg) return;

  const ds = GSC_CHART_DATASETS[tfKey] || GSC_CHART_DATASETS['90d'];
  if (!ds) return;

  const width = svg.clientWidth || 1100;
  const height = 240;
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);

  const labelsList = ds.labels || ds.dateLabels || [];
  const pointsCount = labelsList.length;
  const paddingX = 40;
  const paddingY = 20;
  const usableW = width - paddingX * 2;
  const usableH = height - paddingY * 2;

  const getX = (i) => paddingX + (i / Math.max(1, pointsCount - 1)) * usableW;

  const maxClicks = Math.max(...ds.clicks, 1);
  const maxImp = Math.max(...ds.impressions, 1);
  const maxCtr = Math.max(...ds.ctr, 1);
  const maxPos = 20; // inverted scale (top position = 1 at top)

  const getY_clicks = (v) => height - paddingY - (v / maxClicks) * usableH;
  const getY_imp = (v) => height - paddingY - (v / maxImp) * usableH;
  const getY_ctr = (v) => height - paddingY - (v / maxCtr) * usableH;
  const getY_pos = (v) => paddingY + (v / maxPos) * usableH;

  function buildSpline(pts) {
    if (pts.length < 2) return '';
    let d = `M ${pts[0].x} ${pts[0].y}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[Math.max(0, i - 1)];
      const p1 = pts[i];
      const p2 = pts[i + 1];
      const p3 = pts[Math.min(pts.length - 1, i + 2)];
      const cp1x = p1.x + (p2.x - p0.x) / 6;
      const cp1y = p1.y + (p2.y - p0.y) / 6;
      const cp2x = p2.x - (p3.x - p1.x) / 6;
      const cp2y = p2.y - (p3.y - p1.y) / 6;
      d += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)}, ${cp2x.toFixed(1)} ${cp2y.toFixed(1)}, ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`;
    }
    return d;
  }

  const clicksPts = ds.clicks.map((v, i) => ({ x: getX(i), y: getY_clicks(v) }));
  const impPts = ds.impressions.map((v, i) => ({ x: getX(i), y: getY_imp(v) }));
  const ctrPts = ds.ctr.map((v, i) => ({ x: getX(i), y: getY_ctr(v) }));
  const posPts = ds.position.map((v, i) => ({ x: getX(i), y: getY_pos(v) }));

  // Horizontal Grid Lines
  let gridHtml = '';
  for (let g = 0; g <= 4; g++) {
    const gy = paddingY + (g / 4) * usableH;
    gridHtml += `<line x1="${paddingX}" y1="${gy}" x2="${width - paddingX}" y2="${gy}" stroke="var(--border-subtle)" stroke-dasharray="3,3" stroke-width="1"/>`;
  }

  // Date Labels on X Axis
  let labelsHtml = '';
  labelsList.forEach((label, i) => {
    labelsHtml += `<text x="${getX(i)}" y="${height - 2}" text-anchor="middle" font-size="11" fill="var(--text-muted)">${label}</text>`;
  });

  const clicksPath = gscVisibleMetrics.clicks ? `<path d="${buildSpline(clicksPts)}" fill="none" stroke="var(--chart-clicks)" stroke-width="2.5" filter="drop-shadow(0 2px 4px rgba(77,174,235,0.3))"/>` : '';
  const impPath = gscVisibleMetrics.impressions ? `<path d="${buildSpline(impPts)}" fill="none" stroke="var(--chart-impressions)" stroke-width="2" stroke-dasharray="4,4"/>` : '';
  const ctrPath = gscVisibleMetrics.ctr ? `<path d="${buildSpline(ctrPts)}" fill="none" stroke="var(--chart-ctr)" stroke-width="2" filter="drop-shadow(0 2px 4px rgba(16,185,129,0.25))"/>` : '';
  const posPath = gscVisibleMetrics.position ? `<path d="${buildSpline(posPts)}" fill="none" stroke="var(--chart-position)" stroke-width="2" filter="drop-shadow(0 2px 4px rgba(245,158,11,0.25))"/>` : '';

  svg.innerHTML = gridHtml + clicksPath + impPath + ctrPath + posPath + labelsHtml;
}

function toggleGscMetric(metricKey) {
  gscVisibleMetrics[metricKey] = !gscVisibleMetrics[metricKey];
  const card = document.getElementById(`gsc-card-${metricKey}`);
  if (card) {
    if (gscVisibleMetrics[metricKey]) {
      card.classList.remove('inactive');
    } else {
      card.classList.add('inactive');
    }
  }
  renderGscChart(currentTimeframe);
}

// 6. CTR Surge Checklist Progress
function initSurgeChecklist() {
  let saved = {};
  try {
    const raw = localStorage.getItem('octane_ctr_growth_checklist_v1');
    if (raw) saved = JSON.parse(raw);
  } catch (e) {}

  let completedCount = 0;
  for (let i = 1; i <= 7; i++) {
    const chk = document.getElementById(`chk-action-${i}`);
    const card = document.getElementById(`action-card-${i}`);
    if (chk) {
      chk.checked = !!saved[i];
      if (chk.checked) {
        completedCount++;
        if (card) card.classList.add('completed');
      }
      chk.addEventListener('change', (e) => {
        saved[i] = e.target.checked;
        if (card) {
          if (e.target.checked) card.classList.add('completed');
          else card.classList.remove('completed');
        }
        localStorage.setItem('octane_ctr_growth_checklist_v1', JSON.stringify(saved));
        updateChecklistProgress();
        saveStateToCloud();
      });
    }
  }
  updateChecklistProgress();
}

function updateChecklistProgress() {
  let checked = 0;
  for (let i = 1; i <= 7; i++) {
    const c = document.getElementById(`chk-action-${i}`);
    if (c && c.checked) checked++;
  }
  const pct = Math.round((checked / 7) * 100);
  const fill = document.getElementById('checklist-progress-fill');
  const txt = document.getElementById('checklist-progress-txt');
  if (fill) fill.style.width = `${pct}%`;
  if (txt) txt.textContent = `${checked} of 7 (${pct}%)`;
}

function copySurgeMeta(title, desc) {
  const text = `Title: ${title}\nDescription: ${desc}`;
  navigator.clipboard.writeText(text).then(() => showToast('📋 Meta tags copied to clipboard!'));
}

// 7. JIT Virtualized Modals (Zero initial DOM weight)
function openModal(id) {
  const modal = document.getElementById(id);
  if (modal) {
    modal.classList.remove('hidden');
    document.body.style.overflow = 'hidden';
  }
}

function closeModal(id) {
  const modal = document.getElementById(id);
  if (modal) {
    modal.classList.add('hidden');
    document.body.style.overflow = '';
  }
}

// HubSpot Lead Inspector Modal (Gated API Fetch)
let ACTIVE_LOADED_LEADS = [];

async function openLeadModal() {
  const container = document.getElementById('lead-modal-content');
  if (!container) return;

  openModal('modal-hubspot-leads');
  container.innerHTML = `
    <div style="padding: 2.5rem; text-align: center; color: var(--text-muted);">
      <span class="pulse-dot" style="display: inline-block; margin-bottom: 0.5rem;"></span>
      <div>Connecting to secure leads endpoint...</div>
    </div>
  `;

  try {
    const tf = (JOURNEY_DATA && JOURNEY_DATA.timeframe) ? JOURNEY_DATA.timeframe : '90d';
    const res = await fetch(`/api/leads?timeframe=${tf}`);
    if (!res.ok) {
      container.innerHTML = `
        <div style="padding: 2rem; text-align: center; color: #dc2626; font-size: 0.88rem;">
          Authentication required to view customer leads. Please log in again.
        </div>
      `;
      return;
    }
    const data = await res.json();
    const leads = (data && data.leads) ? data.leads : [];
    ACTIVE_LOADED_LEADS = leads;

    const counts = data.channelCounts || {
      all: leads.length,
      marketing: leads.filter(l => l.channelId !== 'direct').length,
      website: leads.filter(l => l.channelId === 'website').length,
      email: leads.filter(l => l.channelId === 'email').length,
      meeting: leads.filter(l => l.channelId === 'meeting').length,
      search: leads.filter(l => l.channelId === 'search').length,
      direct: leads.filter(l => l.channelId === 'direct').length
    };

    container.innerHTML = `
      <div style="display: flex; justify-content: space-between; align-items: center; gap: 0.75rem; flex-wrap: wrap;">
        <input type="text" id="lead-search-box" class="modal-search-input" style="flex: 1; min-width: 260px;" placeholder="Search name, company, email, channel, landing page..." oninput="filterLeadItems(this.value)">
        <button class="btn-header-action" onclick="exportLeadsCSV()" style="white-space: nowrap; font-size: 0.78rem;">
          📥 Export CSV
        </button>
      </div>

      <div style="font-size: 0.76rem; color: var(--text-muted); margin-top: 0.65rem;">
        Filter by Acquisition Source:
      </div>

      <div style="display: flex; gap: 0.4rem; flex-wrap: wrap; margin-top: 0.35rem;">
        <span class="telemetry-pill live-active" onclick="filterLeadChannel('marketing', this)">🎯 Marketing Inbound (${counts.marketing})</span>
        <span class="telemetry-pill" onclick="filterLeadChannel('website', this)">🌐 Website Forms (${counts.website})</span>
        <span class="telemetry-pill" onclick="filterLeadChannel('email', this)">📧 Email Sync (${counts.email})</span>
        <span class="telemetry-pill" onclick="filterLeadChannel('meeting', this)">📅 Calendar Bookings (${counts.meeting})</span>
        <span class="telemetry-pill" onclick="filterLeadChannel('search', this)">🔍 Google Search (${counts.search})</span>
        <span class="telemetry-pill" onclick="filterLeadChannel('direct', this)">👤 Direct CRM (${counts.direct})</span>
        <span class="telemetry-pill" onclick="filterLeadChannel('all', this)">📋 All Records (${counts.all})</span>
      </div>

      <div id="leads-list-scroll" style="display: flex; flex-direction: column; gap: 0.75rem; max-height: 55vh; overflow-y: auto; margin-top: 0.85rem;">
        ${leads.length === 0 ? `
          <div style="padding: 2.5rem; text-align: center; color: var(--text-muted); font-size: 0.88rem;">
            No inbound leads recorded for this timeframe (${tf}).
          </div>
        ` : leads.map(l => `
          <div class="radar-page-item lead-row-item" data-text="${(l.name + ' ' + l.company + ' ' + (l.email || '') + ' ' + (l.channelLabel || '') + ' ' + (l.conversionEvent || l.event || '') + ' ' + (l.landingUrl || '')).toLowerCase()}" data-channel="${l.channelId || 'direct'}">
            <div style="flex: 1;">
              <div style="display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap;">
                <span style="font-weight: 700; color: var(--text-primary); font-size: 0.9rem;">${l.name}</span>
                <span style="font-weight: 500; color: var(--text-muted); font-size: 0.82rem;">&bull; ${l.jobTitle || 'Executive'} (${l.company})</span>
                <span class="telemetry-pill" style="font-size: 0.7rem; padding: 0.15rem 0.45rem;">${l.channelIcon || '👤'} ${l.channelLabel || 'Direct CRM'}</span>
              </div>
              <div style="font-size: 0.76rem; color: var(--brand-primary); margin-top: 0.25rem;">
                ${l.conversionEvent || l.event || 'Direct Contact'} &bull; <span style="color: var(--text-muted);">${l.landingUrl || l.url || ''}</span>
              </div>
              <div style="font-size: 0.72rem; color: var(--text-muted); margin-top: 0.2rem;">
                ${l.location || 'Australia'} &bull; Signed up ${l.when || l.recency || 'recently'} &bull; <strong style="color: var(--brand-primary);">${l.lifecycleStage || l.status || 'MQL'}</strong>
              </div>
            </div>
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <a href="mailto:${encodeURIComponent(l.email || '')}?subject=Following%20up%20from%20Octane" class="btn-header-action" style="font-size: 0.74rem; padding: 0.35rem 0.65rem; text-decoration: none;" title="Send email to ${l.name}">
                ✉️ Email
              </a>
            </div>
          </div>
        `).join('')}
        <div id="leads-empty-state" style="display: none; padding: 2.5rem; text-align: center; color: var(--text-muted); font-size: 0.88rem;">
          No leads match your active filter or search query.
        </div>
      </div>
    `;

    // Apply default filter to show marketing leads only
    currentChannelFilter = 'marketing';
    currentSearchText = '';
    applyLeadFilters();
  } catch (err) {
    container.innerHTML = `
      <div style="padding: 2rem; text-align: center; color: #dc2626; font-size: 0.88rem;">
        Error fetching verified leads from secure API.
      </div>
    `;
  }
}

let currentChannelFilter = 'marketing';
let currentSearchText = '';

function applyLeadFilters() {
  const items = document.querySelectorAll('.lead-row-item');
  let visibleCount = 0;
  items.forEach(el => {
    const textMatch = !currentSearchText || el.getAttribute('data-text').includes(currentSearchText);
    let channelMatch = false;
    const ch = el.getAttribute('data-channel');
    if (currentChannelFilter === 'all') {
      channelMatch = true;
    } else if (currentChannelFilter === 'marketing') {
      channelMatch = (ch !== 'direct');
    } else {
      channelMatch = (ch === currentChannelFilter);
    }
    const isVis = (textMatch && channelMatch);
    el.style.display = isVis ? 'flex' : 'none';
    if (isVis) visibleCount++;
  });

  const emptyMsg = document.getElementById('leads-empty-state');
  if (emptyMsg) {
    emptyMsg.style.display = (items.length > 0 && visibleCount === 0) ? 'block' : 'none';
  }
}

function filterLeadItems(query) {
  currentSearchText = query.toLowerCase();
  applyLeadFilters();
}

function filterLeadChannel(channelId, pillEl) {
  currentChannelFilter = channelId;
  document.querySelectorAll('#modal-hubspot-leads .telemetry-pill').forEach(p => p.classList.remove('live-active'));
  if (pillEl) pillEl.classList.add('live-active');
  applyLeadFilters();
}

function exportLeadsCSV() {
  if (!ACTIVE_LOADED_LEADS || ACTIVE_LOADED_LEADS.length === 0) {
    alert('No leads available to export.');
    return;
  }

  let toExport = ACTIVE_LOADED_LEADS;
  if (currentChannelFilter === 'marketing') {
    toExport = ACTIVE_LOADED_LEADS.filter(l => l.channelId !== 'direct');
  } else if (currentChannelFilter !== 'all') {
    toExport = ACTIVE_LOADED_LEADS.filter(l => l.channelId === currentChannelFilter);
  }

  const headers = ['Name', 'Email', 'Company', 'Job Title', 'Channel', 'Conversion Event', 'Landing Page', 'Location', 'Lifecycle Stage', 'Date'];
  const rows = toExport.map(l => [
    `"${(l.name || '').replace(/"/g, '""')}"`,
    `"${(l.email || '').replace(/"/g, '""')}"`,
    `"${(l.company || '').replace(/"/g, '""')}"`,
    `"${(l.jobTitle || '').replace(/"/g, '""')}"`,
    `"${(l.channelLabel || 'Direct CRM').replace(/"/g, '""')}"`,
    `"${(l.conversionEvent || '').replace(/"/g, '""')}"`,
    `"${(l.landingUrl || '').replace(/"/g, '""')}"`,
    `"${(l.location || '').replace(/"/g, '""')}"`,
    `"${(l.lifecycleStage || '').replace(/"/g, '""')}"`,
    `"${(l.when || '').replace(/"/g, '""')}"`
  ]);

  const csvContent = 'data:text/csv;charset=utf-8,' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement('a');
  link.setAttribute('href', encodedUri);
  link.setAttribute('download', `octane_leads_${currentChannelFilter}_${Date.now()}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

