// FAQPage Schema Modal
function openSurgeSchemaModal(id) {
  activeSchemaId = id;
  const schema = SURGE_SCHEMAS[id] || SURGE_SCHEMAS[1];
  const titleEl = document.getElementById('schema-modal-title');
  const codeEl = document.getElementById('schema-modal-code');
  if (titleEl) titleEl.textContent = schema.title || 'FAQPage JSON-LD Schema';
  if (codeEl) codeEl.textContent = '<script type="application/ld+json">\n' + schema.json + '\n</script>';
  openModal('modal-surge-schema');
}

function copyActiveSurgeSchema() {
  const schema = SURGE_SCHEMAS[activeSchemaId] || SURGE_SCHEMAS[1];
  const payload = '<script type="application/ld+json">\n' + schema.json + '\n</script>';
  navigator.clipboard.writeText(payload).then(() => {
    showToast('✅ Copied FAQ JSON-LD Schema to Clipboard!');
    closeModal('modal-surge-schema');
  });
}

// 8. Interactive Journey Explorer Canvas Engine
function renderStage1() {
  const container = document.getElementById('stage-1-list');
  if (!container) return;

  const channels = JOURNEY_DATA.channels || [];
  container.innerHTML = channels.map(ch => `
    <div class="canvas-node-card ${ch.id === activeChannelKey ? 'active' : ''}" onclick="selectChannel('${ch.id}', this)">
      <div class="canvas-node-header">
        <span class="canvas-node-title">${ch.title || ch.name || 'Inbound Channel'}</span>
        <span class="canvas-node-share">${ch.share || '0%'}</span>
      </div>
      <div class="canvas-node-metrics">
        <span>Sessions: <strong>${(ch.sessions || 0).toLocaleString()}</strong></span>
        <span>Users: <strong>${(ch.users || 0).toLocaleString()}</strong></span>
      </div>
    </div>
  `).join('');

  renderStage2();
}

