// 9. SVG Bezier Curves Between Active Nodes
function redrawAllEdges() {
  const svg = document.getElementById('canvas-edges-svg');
  if (!svg || currentViewMode !== 'explorer') return;

  const activeNodes = Array.from(document.querySelectorAll('#canvas-world .canvas-node-card.active'));
  if (activeNodes.length < 2) {
    svg.innerHTML = '';
    return;
  }

  const svgRect = svg.getBoundingClientRect();
  let pathsHtml = '';

  for (let i = 0; i < activeNodes.length - 1; i++) {
    const nodeA = activeNodes[i];
    const nodeB = activeNodes[i + 1];
    const rectA = nodeA.getBoundingClientRect();
    const rectB = nodeB.getBoundingClientRect();

    const x1 = (rectA.right - svgRect.left) / canvasScale;
    const y1 = (rectA.top + rectA.height / 2 - svgRect.top) / canvasScale;
    const x2 = (rectB.left - svgRect.left) / canvasScale;
    const y2 = (rectB.top + rectB.height / 2 - svgRect.top) / canvasScale;

    const dx = (x2 - x1) * 0.5;
    const d = `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`;
    pathsHtml += `<path d="${d}" class="edge-path"/>`;
  }

  svg.innerHTML = pathsHtml;
}

// 10. Sticky Notes & Graph Connections
function renderAllStickyNotes() {
  const container = document.getElementById('sticky-notes-layer');
  if (!container) return;

  container.innerHTML = STICKY_NOTES.map(n => `
    <div id="${n.id}" class="sticky-note ${n.color || 'yellow'}" style="left: ${n.x}px; top: ${n.y}px; width: ${n.width || 240}px; height: ${n.height || 140}px;">
      <div class="sticky-header">
        <span class="sticky-title">Task / Note</span>
        <div class="sticky-actions">
          <button onclick="cycleStickyColor('${n.id}')" title="Change Color" style="font-size: 0.8rem;">🎨</button>
          <button onclick="deleteStickyNote('${n.id}')" title="Delete Note" style="font-size: 0.8rem;">✕</button>
        </div>
      </div>
      <textarea class="sticky-textarea" oninput="updateStickyText('${n.id}', this.value)">${n.text}</textarea>
    </div>
  `).join('');

  makeStickyNotesDraggable();
}

function makeStickyNotesDraggable() {
  document.querySelectorAll('.sticky-note').forEach(el => {
    let startX = 0, startY = 0, initialLeft = 0, initialTop = 0;
    const header = el.querySelector('.sticky-header');
    if (!header) return;

    header.onmousedown = (e) => {
      e.stopPropagation();
      startX = e.clientX;
      startY = e.clientY;
      initialLeft = parseInt(el.style.left, 10) || 0;
      initialTop = parseInt(el.style.top, 10) || 0;

      document.onmousemove = (moveEvent) => {
        const dx = (moveEvent.clientX - startX) / canvasScale;
        const dy = (moveEvent.clientY - startY) / canvasScale;
        el.style.left = `${initialLeft + dx}px`;
        el.style.top = `${initialTop + dy}px`;
      };

      document.onmouseup = () => {
        document.onmousemove = null;
        document.onmouseup = null;
        const note = STICKY_NOTES.find(n => n.id === el.id);
        if (note) {
          note.x = parseInt(el.style.left, 10);
          note.y = parseInt(el.style.top, 10);
          saveStickyNotesLocally();
          saveStateToCloud();
        }
      };
    };
  });
}

function addNewStickyNote() {
  if (currentViewMode !== 'explorer') {
    switchViewMode('explorer', document.getElementById('btn-mode-explore'));
  }
  const newId = `note-${Date.now()}`;
  const newNote = {
    id: newId,
    x: 80 - canvasPanX / canvasScale,
    y: 840 - canvasPanY / canvasScale,
    width: 240,
    height: 140,
    color: 'yellow',
    text: 'New Strategic Task'
  };
  STICKY_NOTES.push(newNote);
  renderAllStickyNotes();
  saveStickyNotesLocally();
  saveStateToCloud();
  showToast('📝 New sticky note added!');
}

function deleteStickyNote(id) {
  STICKY_NOTES = STICKY_NOTES.filter(n => n.id !== id);
  renderAllStickyNotes();
  saveStickyNotesLocally();
  saveStateToCloud();
}

function cycleStickyColor(id) {
  const colors = ['yellow', 'pink', 'green', 'blue', 'purple'];
  const note = STICKY_NOTES.find(n => n.id === id);
  if (note) {
    const idx = colors.indexOf(note.color);
    note.color = colors[(idx + 1) % colors.length];
    renderAllStickyNotes();
    saveStickyNotesLocally();
    saveStateToCloud();
  }
}

function updateStickyText(id, text) {
  const note = STICKY_NOTES.find(n => n.id === id);
  if (note) {
    note.text = text;
    saveStickyNotesLocally();
    debouncedCloudSave();
  }
}

function saveStickyNotesLocally() {
  localStorage.setItem('octane_canvas_sticky_notes', JSON.stringify(STICKY_NOTES));
}

// 11. Figma Canvas Engine (Pan & Zoom)
function initFigmaCanvasEngine() {
  const vp = document.getElementById('canvas-viewport');
  const world = document.getElementById('canvas-world');
  if (!vp || !world) return;

  vp.addEventListener('wheel', (e) => {
    if (e.ctrlKey || e.metaKey || true) {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      zoomCanvas(zoomFactor, e.clientX, e.clientY);
    }
  }, { passive: false });

  vp.addEventListener('mousedown', (e) => {
    if (e.target.closest('.sticky-note') || e.target.closest('.canvas-node-card') || e.target.closest('.canvas-zoom-hud')) return;
    isPanning = true;
    startPanX = e.clientX - canvasPanX;
    startPanY = e.clientY - canvasPanY;
    vp.classList.add('is-dragging');
  });

  window.addEventListener('mousemove', (e) => {
    if (!isPanning) return;
    canvasPanX = e.clientX - startPanX;
    canvasPanY = e.clientY - startPanY;
    applyCanvasTransform();
  });

  window.addEventListener('mouseup', () => {
    if (isPanning) {
      isPanning = false;
      vp.classList.remove('is-dragging');
    }
  });
}

function zoomCanvas(factor, clientX, clientY) {
  const oldScale = canvasScale;
  canvasScale = Math.min(2.5, Math.max(0.4, canvasScale * factor));
  const lvl = document.getElementById('zoom-hud-level');
  if (lvl) lvl.textContent = `${Math.round(canvasScale * 100)}%`;
  applyCanvasTransform();
  redrawAllEdges();
}

function resetCanvasView() {
  canvasScale = 1.0;
  canvasPanX = 0;
  canvasPanY = 0;
  const lvl = document.getElementById('zoom-hud-level');
  if (lvl) lvl.textContent = '100%';
  applyCanvasTransform();
  redrawAllEdges();
}

function applyCanvasTransform() {
  const world = document.getElementById('canvas-world');
  if (world) {
    world.style.transform = `translate(${canvasPanX}px, ${canvasPanY}px) scale(${canvasScale})`;
  }
}

// 12. Background Telemetry & Cloud Persistence
async function syncRealtimeGA4() {
  try {
    const res = await fetch('/api/realtime?t=' + Date.now());
    const countEl = document.getElementById('active-visitors-count');
    const stripTag = document.getElementById('status-tag-active');
    const heroTitle = document.getElementById('hero-reading-title');
    const geoEl = document.getElementById('reading-geo-text');
    const radarCount = document.getElementById('radar-live-count');
    const radarDevice = document.getElementById('radar-device-split');
    const radarPulse = document.getElementById('radar-pulse-dot');
    const statusPulse = document.getElementById('status-pulse-dot');
    const pagesCount = document.getElementById('radar-pages-count');
    const geoCount = document.getElementById('radar-geo-count');
    const radarPagesList = document.getElementById('radar-live-pages-list');
    const radarGeoList = document.getElementById('radar-live-geo-list');

    if (!res.ok) {
      if (countEl) countEl.textContent = '0 Live Visitors';
      if (radarCount) radarCount.textContent = '0 Online';
      if (stripTag) stripTag.innerHTML = '<span class="pulse-dot idle"></span> Realtime Stream: Connecting...';
      if (heroTitle) heroTitle.textContent = 'Awaiting Live Traffic';
      if (geoEl) geoEl.textContent = 'Listening for visits 🌐';
      return;
    }

    const data = await res.json();
    const count = (data && typeof data.activeUsersTotal === 'number') ? data.activeUsersTotal : 0;

    if (countEl) countEl.textContent = `${count} Live Visitors`;
    if (radarCount) radarCount.textContent = `${count} Online`;

    if (count > 0) {
      if (radarPulse) radarPulse.className = 'pulse-dot';
      if (statusPulse) statusPulse.className = 'pulse-dot';
      if (stripTag) stripTag.innerHTML = `<span class="pulse-dot"></span> Active Visitors: ${count} Right Now`;
      if (radarDevice) radarDevice.textContent = data.deviceSplit || 'Live Traffic';

      if (data.activePages && data.activePages.length > 0) {
        const topPage = data.activePages[0];
        if (heroTitle) heroTitle.textContent = topPage.pageTitle || topPage.path || 'Active Page';
        if (geoEl) geoEl.textContent = topPage.locations ? `Geo: ${topPage.locations.join(', ')} 🌐` : 'Live Visit Active 🌐';

        if (pagesCount) pagesCount.textContent = `${data.activePages.length} Active Pages`;
        if (radarPagesList) {
          radarPagesList.innerHTML = data.activePages.map(p => `
            <div class="radar-page-item">
              <span class="radar-page-name">${p.pageTitle || p.path || 'Page'}</span>
              <span class="radar-user-count">${p.users || 1} Active Reader${(p.users || 1) > 1 ? 's' : ''}</span>
            </div>
          `).join('');
        }
      }

      if (data.locations && data.locations.length > 0) {
        if (geoCount) geoCount.textContent = `${data.locations.length} Locations`;
        if (radarGeoList) {
          radarGeoList.innerHTML = data.locations.map(loc => `
            <div class="radar-page-item">
              <span class="radar-page-name">🌏 ${loc.city || loc.country}</span>
              <span class="radar-user-count">${loc.users || 1} Reader${(loc.users || 1) > 1 ? 's' : ''}</span>
            </div>
          `).join('');
        }
      }
    } else {
      if (radarPulse) radarPulse.className = 'pulse-dot idle';
      if (statusPulse) statusPulse.className = 'pulse-dot idle';
      if (stripTag) stripTag.innerHTML = '<span class="pulse-dot idle"></span> Active Visitors: 0 Right Now';
      if (radarDevice) radarDevice.textContent = 'Awaiting Inbound Traffic';
      if (heroTitle) heroTitle.textContent = 'Awaiting Live Traffic';
      if (geoEl) geoEl.textContent = 'Listening for visits 🌐';
      if (pagesCount) pagesCount.textContent = '0 Active Pages';
      if (geoCount) geoCount.textContent = '0 Locations';
      if (radarPagesList) {
        radarPagesList.innerHTML = `
          <div style="padding: 1.25rem; text-align: center; color: var(--text-muted); font-size: 0.8rem;">
            No concurrent readers on site right now. Listening for new visits...
          </div>
        `;
      }
      if (radarGeoList) {
        radarGeoList.innerHTML = `
          <div style="padding: 1.25rem; text-align: center; color: var(--text-muted); font-size: 0.8rem;">
            No geographic sessions active in the past 30 minutes.
          </div>
        `;
      }
    }
  } catch (err) {
    const countEl = document.getElementById('active-visitors-count');
    if (countEl) countEl.textContent = '0 Live Visitors';
  }
}

async function syncLiveTelemetry() {
  try {
    const [telemRes, blogRes] = await Promise.allSettled([
      fetch('/api/telemetry?t=' + Date.now()),
      fetch('/api/get-blog-stats?period=last90')
    ]);

    if (telemRes.status === 'fulfilled' && telemRes.value && telemRes.value.ok) {
      const fresh = await telemRes.value.json();
      if (fresh && fresh['90d']) Object.assign(TIMEFRAMES_DATA, fresh);
    }
    if (blogRes.status === 'fulfilled' && blogRes.value && blogRes.value.ok) {
      const freshBlog = await blogRes.value.json();
      if (freshBlog && freshBlog.blogs) window.LIVE_ACTIVE_BLOGS = freshBlog.blogs;
    }
    updateExecutiveBriefing();
  } catch (e) {}
}

let cloudSaveTimeout = null;
function debouncedCloudSave() {
  clearTimeout(cloudSaveTimeout);
  cloudSaveTimeout = setTimeout(saveStateToCloud, 2000);
}

async function saveStateToCloud() {
  const btn = document.getElementById('btn-save-cloud');
  if (btn) btn.textContent = '⏳ Saving...';

  let checklistState = {};
  try {
    const saved = localStorage.getItem('octane_ctr_growth_checklist_v1');
    if (saved) checklistState = JSON.parse(saved);
  } catch (e) {}

  const payload = {
    notes: STICKY_NOTES,
    connections: STICKY_CONNECTIONS,
    checklist: checklistState,
    updatedAt: Date.now()
  };

  try {
    await fetch('/api/state', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    showToast('☁️ Saved to Cloud & Synced!');
  } catch (err) {
    showToast('💾 Saved locally (Offline)');
  } finally {
    if (btn) btn.textContent = '💾 Save & Sync';
  }
}

async function syncStateFromCloud() {
  try {
    const res = await fetch('/api/state');
    if (!res.ok) return;
    const st = await res.json();
    if (st.notes && Array.isArray(st.notes)) STICKY_NOTES = st.notes;
    if (st.connections && Array.isArray(st.connections)) STICKY_CONNECTIONS = st.connections;
    renderAllStickyNotes();
  } catch (e) {}
}

function showToast(msg) {
  const toast = document.getElementById('toast');
  if (toast) {
    toast.textContent = msg;
    toast.style.display = 'block';
    setTimeout(() => { toast.style.display = 'none'; }, 3000);
  }
}

function copySnapshot() {
  navigator.clipboard.writeText(window.location.href).then(() => showToast('🔗 Dashboard snapshot link copied!'));
}

function copySeoAuditReport() {
  const report = `Octane Blog Continuous Scroll Architecture Audit Report
Target: Blog Post Layout 65127478077

Physical Telemetry Findings:
- Page Size: 784 KB (Standard: 30-50 KB, 15x over limit)
- Articles in Single DOM: 78 Full Posts
- Heading Tags: 11 H1s, 191 H2s
- Word Count: 30,465 words per page

Core Issues & Failure Explanations:
1. 78 Full Articles Dumped in One HTML Page: Burns crawl budget, spikes load times, exhausts mobile memory.
2. Site-Wide Content Cannibalization: The exact same 30,000 words are duplicated across dozens of URLs.
3. Semantic Heading Chaos: 11 H1s and 191 H2s destroy search engine topic classification.
4. Googlebot Never Scrolls: replaceState never triggers for search crawlers, leaving articles trapped.
5. Canonical Conflict: Mismatched content leads Google to ignore canonical tags completely.

Recommended Google Search Central Fix:
Deliver only 1 article per page on initial load (<50 KB, 1 H1). Fetch subsequent articles dynamically on scroll or via explicit Next Article links.`;

  navigator.clipboard.writeText(report)
    .then(() => showToast('📋 Continuous Scroll SEO Audit copied!'))
    .catch(() => showToast('✅ Copied to clipboard!'));
}

// Initialization on DOM Ready
window.addEventListener('DOMContentLoaded', () => {
  initTheme();
  updateExecutiveBriefing();
  renderGscChart('90d');
  initSurgeChecklist();
  initFigmaCanvasEngine();
  syncStateFromCloud();
  syncRealtimeGA4();
  syncLiveTelemetry();

  // Background Telemetry Loops
  setInterval(syncRealtimeGA4, 20000);
  setInterval(syncLiveTelemetry, 60000);

  // Resize listener for SVG curves
  window.addEventListener('resize', () => {
    if (currentViewMode === 'executive') renderGscChart(currentTimeframe);
    else redrawAllEdges();
  });

  // Escape key listener to dismiss open modals
  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      document.querySelectorAll('.modal-backdrop:not(.hidden)').forEach(m => {
        closeModal(m.id);
      });
    }
  });
});
